    whatsapp_api_key: $env.WHATSAPP_API_KEY || '',
    whatsapp_target_number: $env.WHATSAPP_TARGET_NUMBER || ''
  }
}];

const inputData = $('Normalize Input').item.json;
const historyResp = ($('Fetch Memory History') && $('Fetch Memory History').item && $('Fetch Memory History').item.json) || {};
const manifestResp = ($('Fetch AI Manifest') && $('Fetch AI Manifest').item && $('Fetch AI Manifest').item.json) || {};

const historyMessages = Array.isArray(historyResp.messages) ? historyResp.messages : [];
let rawEndpoints = Array.isArray(manifestResp.endpoints) && manifestResp.endpoints.length > 0 ? manifestResp.endpoints : [];

const defaultEndpoints = [
  {
    action: 'get_store_metrics',
    description: 'Melihat ringkasan metrik performa toko (total earnings, total orders, customers, balance)',
    params: [],
    method: 'GET',
