    action: 'report_customer_issue',
    description: 'Melaporkan komplain, kendala teknis atau masalah pelanggan seperti fitur yang tidak dapat diakses, tombol rusak, bug sistem, error, atau keluhan layanan, dan menerbitkan tiket gangguan resmi untuk tim internal.',
    params: ['category', 'feature_name', 'description', 'urgency'],
    method: 'POST',
    path: '/api/v1/tickets'
  },
  {
    action: 'get_user_profile',
    description: 'Melihat data profil dan status akun pengguna saat ini',
    params: [],
    method: 'GET',
    path: '/api/v1/user/{user_id}/profile'
  },
  {
    action: 'get_transactions',
    description: 'Melihat riwayat transaksi penjualan dan order pengguna',
    params: ['status', 'limit', 'date_from', 'date_to'],
    method: 'GET',
    path: '/api/v1/user/{user_id}/transactions'
  }
];

if (rawEndpoints.length === 0) {
  rawEndpoints = defaultEndpoints;
} else if (!rawEndpoints.some(e => e.action === 'report_customer_issue')) {
  rawEndpoints.push(defaultEndpoints.find(e => e.action === 'report_customer_issue'));
}

function sanitizePII(text) {
  if (!text || typeof text !== 'string') return text;
  return text
    .replace(/\b(?:pin|otp|password|kata\s*sandi|token|secret)\s*[:=]\s*(\S+)/gi, (m, v) => m.replace(v, '[PIN/PASSWORD_DISAMARKAN]'))
    .replace(/\b\d{4}[ -]?\d{4}[ -]?\d{4}[ -]?\d{4}\b|\b\d{16}\b/g, '[NOMOR_KTP_DISAMARKAN]')
    .replace(/(?:\+?62|0)8[0-9]{1,3}[ -]?[0-9]{3,4}[ -]?[0-9]{3,5}\b/g, '[NOMOR_HP_DISAMARKAN]')
    .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g, '[EMAIL_DISAMARKAN]')
    .replace(/\b(?:\d{4}[ -]?){3}\d{4}\b/g, '[KARTU_KREDIT_DISAMARKAN]');
}

const safeCapabilities = rawEndpoints.map(ep => ({
  action: ep.action,
  description: ep.description,
  params: ep.params || [],
  method: ep.method || 'GET',
  path: ep.path || '',
  current_data: ep.current_data || undefined
}));

let systemInstruction = `Anda adalah AI INTENT PARSER cerdas untuk asisten percakapan sistem aplikasi.\n\n`;
systemInstruction += `🛡️ ATURAN PRIVASI & KEAMANAN KETAT (MANDATORY):\n`;
systemInstruction += `- Anda DILARANG KERAS membaca, menanyakan, meminta, atau menyimpan data pribadi sensitif (seperti Nomor KTP/NIK, Nomor HP, Email, Password, PIN, Kartu Kredit).\n`;
systemInstruction += `- Seluruh data sensitif yang masuk telah otomatis disamarkan (misalnya: [NOMOR_KTP_DISAMARKAN], [NOMOR_HP_DISAMARKAN], [PIN/PASSWORD_DISAMARKAN]). Jangan pernah menanyakan nilai asli nomor tersebut kepada pengguna.\n\n`;
systemInstruction += `👤 INFORMASI PENGGUNA SAAT INI:\n`;
systemInstruction += `- Nama Pengguna: "${inputData.user_name || 'Pelanggan'}"\n`;
systemInstruction += `- User ID: "${inputData.user_id || 'guest'}"\n\n`;
systemInstruction += `🎯 PERAN & TUGAS UTAMA:\n`;
systemInstruction += `1. Anda bertugas MURNI SEBAGAI INTENT PARSER (Intent Recognition & Slot/Parameter Extraction).\n`;
systemInstruction += `2. Analisis pesan pengguna terkini serta manfaatkan RIWAYAT MEMORI percakapan sebelumnya untuk memahami konteks multi-turn.\n`;
systemInstruction += `3. KHUSUS LAPORAN MASALAH / KENDALA TEKNIS (report_customer_issue):\n`;
systemInstruction += `   - Jika pengguna melaporkan keluhan, masalah sistem, fitur yang tidak dapat diakses atau error, tombol tidak berfungsi, atau komplain, WAJIB tetapkan intent: 'report_customer_issue', matched_action: 'report_customer_issue', dan requires_action: true.\n`;
systemInstruction += `   - Ekstrak parameter: category ('fitur_tidak_dapat_diakses', 'bug_error', 'transaksi', dll.), feature_name (nama fitur/halaman yang terkendala), description (ringkasan masalah), urgency ('tinggi' jika menghambat transaksi/pekerjaan, 'sedang' atau 'rendah').\n`;
systemInstruction += `4. KHUSUS SALAM / SAPAAN PEMBUKA (greeting):\n`;
systemInstruction += `   - Sapa pengguna dengan ramah, sebut nama mereka ("${inputData.user_name || 'Kak'}"), tanyakan apa yang bisa dibantu, dan tawarkan pilihan bantuan seperti cek metrik toko, pantau performa revenue, atau laporkan kendala sistem jika menemukan fitur yang bermasalah.\n`;
systemInstruction += `5. Buat tanggapan singkat ramah ('reply') dalam format HTML sederhana (<b>, <br>) untuk disampaikan ke pengguna.\n\n`;

// 📚 DYNAMIC KNOWLEDGE BASE TEMPLATES DARI CMS (PROJECT MANAGEMENT)
const rawTemplates = manifestResp.support_templates || {};
const templateKeys = Object.keys(rawTemplates);

systemInstruction += `\n📚 PANDUAN KNOWLEDGE BASE DARI CMS (KASUS & SOLUSI RESMI PROJECT MANAGEMENT):\n`;
systemInstruction += `Jika pertanyaan atau keluhan pengguna cocok atau mirip dengan kasus di bawah ini, WAJIB utamakan memberikan panduan solusi terstruktur berikut:\n\n`;

if (templateKeys.length > 0) {
  templateKeys.forEach((key, idx) => {
    const tpl = rawTemplates[key];
    const topic = tpl.topic || key;
    const keywords = Array.isArray(tpl.keywords) ? tpl.keywords.join(', ') : '';
    const steps = Array.isArray(tpl.steps) ? tpl.steps.join('\n  ') : (tpl.raw_solution || '');
    const escalation = tpl.escalation || '';

    systemInstruction += `${idx + 1}. KASUS: "${topic}"\n`;
    systemInstruction += `- Intent Identifikasi: 'troubleshoot_${key}'\n`;
    if (keywords) {
      systemInstruction += `- Kata Kunci / Pertanyaan Terkait: ${keywords}\n`;
    }
    systemInstruction += `- Solusi yang Disampaikan ke Pengguna:\n  ${steps}\n`;
    if (escalation) {
      systemInstruction += `- Panduan Eskalasi: ${escalation}\n`;
    }
    systemInstruction += `\n`;
  });
}

systemInstruction += `📋 DAFTAR ACTION / KAPABILITAS SISTEM YANG TERSEDIA:\n`;
systemInstruction += JSON.stringify(safeCapabilities, null, 2) + `\n\n`;
systemInstruction += `DAFTAR INTENT PERCAKAPAN STANDAR:\n`;
systemInstruction += `- greeting: Salam / sapaan pembuka (halo, selamat pagi/siang, hai, dll.)\n`;
systemInstruction += `- report_customer_issue: Melaporkan masalah/kendala fitur sistem tidak dapat diakses atau bug\n`;
systemInstruction += `- ask_help: Menanyakan apa yang bisa dibantu atau fitur yang tersedia\n`;
systemInstruction += `- chitchat: Percakapan santai, terima kasih, ucapan penutup\n`;
systemInstruction += `- request_clarification: Jika maksud pengguna kurang jelas atau butuh informasi tambahan\n`;
systemInstruction += `- fallback_unknown: Jika di luar konteks sistem aplikasi\n\n`;
systemInstruction += `FORMAT OUTPUT WAJIB (HANYA JSON VALID, TANPA BACKTICK DI LUAR JSON):\n`;
systemInstruction += `{\n`;
systemInstruction += `  "intent": "<nama_action_atau_intent_standar>",\n`;
systemInstruction += `  "confidence": <skor_0_sampai_1>,\n`;
systemInstruction += `  "parameters": {\n`;
systemInstruction += `    "<key>": "<value>"\n`;
systemInstruction += `  },\n`;
systemInstruction += `  "requires_action": <true_jika_perlu_eksekusi_action_lainnya_false>,\n`;
systemInstruction += `  "matched_action": "<nama_action_terpilih_atau_null>",\n`;
systemInstruction += `  "context_note": "<catatan singkat pemahaman konteks dari memory jika multi-turn>",\n`;
systemInstruction += `  "reply": "<tanggapan ramah dalam format HTML sederhana (<b>, <br>)>"\n`;
systemInstruction += `}`; 

const contents = [];

historyMessages.forEach(msg => {
  contents.push({
    role: msg.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: sanitizePII(msg.message) }]
  });
});

contents.push({
  role: 'user',
  parts: [{ text: inputData.message }]
});

// 🔑 Gemini API Key Pool & Rotasi Otomatis
const rawEnvKeys = ($env.GEMINI_API_KEYS || $env.GEMINI_API_KEY || "").trim();
const geminiKeys = rawEnvKeys
  .split(/[,;\s\n\r]+/)
  .map(k => k.trim())
  .filter(k => k.length > 8 && k !== "your_gemini_api_key_here");

let chosenKey = "";
let keyIndex = 0;

if (geminiKeys.length > 0) {
  const seedStr = (inputData.conversation_id || "") + "-" + Date.now() + "-" + Math.random();
  let hash = 0;
  for (let i = 0; i < seedStr.length; i++) {
    hash = ((hash << 5) - hash) + seedStr.charCodeAt(i);
    hash |= 0;
  }
  keyIndex = Math.abs(hash) % geminiKeys.length;
  chosenKey = geminiKeys[keyIndex];
} else {
  chosenKey = $env.GEMINI_API_KEY || "";
}

return [{
  json: {
    conversation_id: inputData.conversation_id,
    user_id: inputData.user_id,
    user_name: inputData.user_name,
    message: inputData.message,
    raw_message_has_pii: inputData.raw_message_has_pii,
    channel: inputData.channel,
    backend_base_url: inputData.backend_base_url,
    internal_api_key: inputData.internal_api_key,
    slack_webhook_url: inputData.slack_webhook_url,
    slack_channel: inputData.slack_channel,
    telegram_bot_token: inputData.telegram_bot_token,
    telegram_chat_id: inputData.telegram_chat_id,
    whatsapp_api_url: inputData.whatsapp_api_url,
    whatsapp_api_key: inputData.whatsapp_api_key,
    whatsapp_target_number: inputData.whatsapp_target_number,
    default_endpoints: rawEndpoints,
    gemini_api_key: chosenKey,
    key_pool: geminiKeys,
    key_index: keyIndex,
    payload: {
      systemInstruction: {
        parts: [{ text: systemInstruction }]
      },
      contents: contents,
      generationConfig: {
        temperature: 0.2,
        maxOutputTokens: 1024,
        responseMimeType: 'application/json'
      }
    }
  }
}];

const geminiResp = $input.first().json;
const promptData = $('Build Gemini Prompt').item.json;
const manifestResp = ($('Fetch AI Manifest') && $('Fetch AI Manifest').item && $('Fetch AI Manifest').item.json) || {};
const keyPool = Array.isArray(promptData.key_pool) ? promptData.key_pool : [];
let usedKeyIndex = promptData.key_index || 0;
let failoverSuccess = false;

// 🔄 Auto-Failover: Jika key terkena 429
if (geminiResp && geminiResp.error && keyPool.length > 1) {
  const isRateLimited = geminiResp.error.code === 429 ||
                        (geminiResp.error.message && /quota|exhausted|rate limit/i.test(geminiResp.error.message)) ||
                        geminiResp.error.status === "RESOURCE_EXHAUSTED";

  if (isRateLimited) {
    for (let i = 1; i < keyPool.length; i++) {
      const backupIndex = (usedKeyIndex + i) % keyPool.length;
      const backupKey = keyPool[backupIndex];
      try {
        const retryUrl = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=" + backupKey;
        const retryRes = await fetch(retryUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(promptData.payload)
        });
        const retryJson = await retryRes.json();
        if (retryJson && !retryJson.error && retryJson.candidates && retryJson.candidates.length > 0) {
          geminiResp = retryJson;
          usedKeyIndex = backupIndex;
          failoverSuccess = true;
          break;
        }
      } catch (err) {}
    }
  }
}

const endpoints = Array.isArray(manifestResp.endpoints) && manifestResp.endpoints.length > 0
  ? manifestResp.endpoints
  : (promptData.default_endpoints || []);

function extractJson(text) {
  if (!text) return null;
  const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  const candidate = match ? match[1].trim() : text.trim();
  try {
    return JSON.parse(candidate);
  } catch (e) {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start !== -1 && end !== -1 && end > start) {
      try {
        return JSON.parse(text.substring(start, end + 1));
      } catch (err) {}
    }
  }
  return null;
}

let rawText = '';
if (geminiResp && geminiResp.candidates && geminiResp.candidates.length > 0) {
  const parts = geminiResp.candidates[0].content && geminiResp.candidates[0].content.parts;
  if (parts && parts.length > 0 && parts[0].text) {
    rawText = parts[0].text;
  }
} else if (geminiResp && geminiResp.error) {
  rawText = JSON.stringify({ intent: 'error', reply: 'Kendala layanan AI: ' + (geminiResp.error.message || 'Error') });
}

let parsed = extractJson(rawText);

if (!parsed) {
  parsed = {
    intent: 'fallback_unknown',
    confidence: 0.5,
    parameters: {},
    requires_action: false,
    matched_action: null,
    reply: rawText || 'Halo! Ada yang bisa kami bantu terkait layanan atau informasi toko?'
  };
}

let finalReply = parsed.reply || '';
const targetAction = parsed.matched_action || parsed.intent;

let isTicketReport = false;
let ticketData = null;
let ticketNumber = '';

// Fulfillment Layer (Safe & Programmatic)
if (targetAction === 'report_customer_issue' || parsed.intent === 'report_customer_issue') {
  isTicketReport = true;
  const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const randCode = Math.floor(1000 + Math.random() * 9000);
  ticketNumber = (parsed.parameters && parsed.parameters.ticket_number) || `TCK-${dateStr}-${randCode}`;

  const featureName = (parsed.parameters && parsed.parameters.feature_name) || 'Fitur Sistem';
  const category = (parsed.parameters && parsed.parameters.category) || 'fitur_tidak_dapat_diakses';
  const description = (parsed.parameters && parsed.parameters.description) || promptData.message;
  const urgency = (parsed.parameters && parsed.parameters.urgency) || 'tinggi';
  const displayName = promptData.user_name || promptData.user_id || 'Pelanggan';

  ticketData = {
    ticket_number: ticketNumber,
    conversation_id: promptData.conversation_id,
    user_id: promptData.user_id,
    user_name: promptData.user_name || '',
    category: category,
    feature_name: featureName,
    description: description,
    urgency: urgency,
    channel: promptData.channel || 'web'
  };

  finalReply = `🎫 <b>Tiket Laporan Gangguan Diterima: #${ticketNumber}</b><br><br>` +
    `Halo <b>${displayName}</b>, kendala terkait <b>Fitur: ${featureName}</b> telah kami catat resmi.<br><br>` +
    `🚨 <b>Pemberitahuan Tim Internal:</b><br>` +
    `Tiket ini telah diteruskan langsung ke <b>Jira Service Management (SUP)</b> & Slack Tim Internal untuk segera diinvestigasi oleh tim teknis.<br><br>` +
    `📋 <b>Rincian Tiket:</b><br>` +
    `• Nomor Tiket: <code>#${ticketNumber}</code><br>` +
    `• Kategori: <i>${category.replace(/_/g, ' ')}</i><br>` +
    `• Urgensi: <b>${urgency.toUpperCase()}</b><br>` +
    `• Status: <b style="color: #2563eb;">OPEN / SEDANG DITINDAKLANJUTI</b><br><br>` +
    `<small style="color: #64748b;">Simpan nomor tiket Anda. Tim teknis segera menangani kendala ini. Terima kasih atas laporannya!</small>`;

} else if (parsed.requires_action && targetAction) {
  const endpointDef = endpoints.find(e => e.action === targetAction);
  if (endpointDef && endpointDef.current_data) {
    const data = endpointDef.current_data;
    if (targetAction === 'get_store_metrics') {
      finalReply = `📊 <b>Ringkasan Metrik Toko:</b><br>` +
        `• Total Earnings: <b>${data.total_earnings || '-'}</b><br>` +
        `• Total Orders: <b>${data.orders || '-'}</b><br>` +
        `• Customers: <b>${data.customers || '-'}</b><br>` +
        `• Saldo Toko: <b>${data.my_balance || '-'}</b><br>` +
        `• Rasio Konversi: <b>${data.conversion_ratio || '-'}</b>`;
    } else if (targetAction === 'get_monthly_revenue') {
      const monthParam = (parsed.parameters && parsed.parameters.month) ? String(parsed.parameters.month).substring(0, 3).toLowerCase() : null;
      let matchedMonthKey = null;
      if (monthParam) {
        matchedMonthKey = Object.keys(data).find(k => k.toLowerCase().startsWith(monthParam));
      }
      if (matchedMonthKey && data[matchedMonthKey]) {
        const mData = data[matchedMonthKey];
        finalReply = `📈 <b>Performa Revenue Bulan ${matchedMonthKey}:</b><br>` +
          `• Orders: <b>${mData.orders}</b><br>` +
          `• Earnings: <b>${mData.earnings}</b><br>` +
          `• Refunds: <b>${mData.refunds}</b>`;
      } else {
        const sampleMonths = Object.keys(data).slice(0, 4);
        finalReply = `📈 <b>Ringkasan Performa Revenue:</b><br>` +
          sampleMonths.map(m => `• <b>${m}</b>: ${data[m].earnings} (${data[m].orders} orders)`).join('<br>') +
          `<br><small>Sebutkan nama bulan tertentu (misal: April, Mei) untuk rincian lebih detail.</small>`;
      }
    } else {
      let title = endpointDef.description || targetAction.replace(/_/g, " ");
      let lines = [`📊 <b>${title.charAt(0).toUpperCase() + title.slice(1)}:</b>`];

      function formatValue(key, val, depth = 0) {
        const indent = depth > 0 ? "&nbsp;&nbsp;&nbsp;&nbsp;" : "";
        const cleanKey = key.replace(/_/g, " ").replace(/\b\w/g, l => l.toUpperCase());
        if (typeof val === "object" && val !== null) {
          if (Array.isArray(val)) {
            lines.push(`${indent}• <b>${cleanKey}:</b>`);
            val.forEach((item, idx) => {
              if (typeof item === "object") {
                lines.push(`${indent}&nbsp;&nbsp;[${idx + 1}] ` + Object.entries(item).map(([ik, iv]) => `<b>${ik}:</b> ${iv}`).join(", "));
              } else {
                lines.push(`${indent}&nbsp;&nbsp;• ${item}`);
              }
            });
          } else {
            lines.push(`${indent}• <b>${cleanKey}:</b>`);
            for (const [subKey, subVal] of Object.entries(val)) {
              formatValue(subKey, subVal, depth + 1);
            }
          }
        } else {
          lines.push(`${indent}• <b>${cleanKey}:</b> ${val}`);
        }
      }

      for (const [k, v] of Object.entries(data)) {
        formatValue(k, v);
      }

      finalReply = (parsed.reply ? `${parsed.reply}<br><br>` : "") + lines.join("<br>");
    }
  }
}

if (promptData.raw_message_has_pii) {
  finalReply += `<br><br><small style="color: #64748b;">🛡️ <i>Catatan Privasi: Data pribadi sensitif (KTP/Nomor HP) Anda otomatis disamarkan sebelum diproses AI.</i></small>`;
}

const usage = (geminiResp && geminiResp.usageMetadata) ? geminiResp.usageMetadata : {};
const promptTokens = usage.promptTokenCount || 0;
const candidatesTokens = usage.candidatesTokenCount || 0;
const totalTokens = usage.totalTokenCount || (promptTokens + candidatesTokens);

